type Backup = import('../objects/Backup')

declare const global: typeof globalThis & { XAccel?: string }

// Body of PATCH /api/backups/path. path is assumed to be a string (the original code passes it to Path.resolve)
type PathBody = { path?: string }
// An uploaded file as express-fileupload puts it on the request: only the members that BackupManager.uploadBackup() reads
type UploadedFile = { name: string; mv: (path: string) => Promise<void> }

type RequestWithUser = Request<{ id?: string }, unknown, PathBody> & { user: User }
type RequestWithBackup = RequestWithUser & { backup: Backup }
// The middleware sets backup when the route has an id
type RequestWithOptionalBackup = RequestWithUser & { backup?: Backup }
type RequestWithFiles = RequestWithUser & { files: { file?: UploadedFile } }

/**
   *
   * @param {RequestWithUser} req
   * @param {Response} res
   */
  upload(this: ApiRouter, req: RequestWithFiles, res: Response) {
    if (!req.files.file) {
      Logger.error('[BackupController] Upload backup invalid')
      return res.sendStatus(500)
    }
    this.backupManager.uploadBackup(req, res)
  }
---
const Path = require('path')
const date = require('../libs/dateAndTime')
const version = require('../../package.json').version

class Backup {
  constructor(data = null) {
    this.id = null
    this.key = null // Special key for pre-version checks
    this.datePretty = null

    this.backupDirPath = null
    this.filename = null
    this.path = null
    this.fullPath = null
    this.serverVersion = null

    this.fileSize = null
    this.createdAt = null

    if (data) {
      this.construct(data)
    }
  }

  get detailsString() {
    const details = []
    details.push(this.id)
    details.push(this.key)
    details.push(this.createdAt)
    details.push(this.serverVersion)
    return details.join('\n')
  }

  construct(data) {
    this.id = data.details[0]
    this.key = data.details[1]
    if (this.key == 1) this.key = null // v2.2.23 and below backups stored '1' here

    this.createdAt = Number(data.details[2])
    this.serverVersion = data.details[3] || null

    this.datePretty = date.format(new Date(this.createdAt), 'ddd, MMM D YYYY HH:mm')

    this.backupDirPath = Path.dirname(data.fullPath)
    this.filename = Path.basename(data.fullPath)
    this.path = Path.join('backups', this.filename)
    this.fullPath = data.fullPath
  }

    }
  }

  setData(backupDirPath) {
    this.id = date.format(new Date(), 'YYYY-MM-DD[T]HHmm')
    this.key = 'sqlite'
    this.datePretty = date.format(new Date(), 'ddd, MMM D YYYY HH:mm')

    this.backupDirPath = backupDirPath

    this.filename = this.id + '.audiobookshelf'
    this.path = Path.join('backups', this.filename)
    this.fullPath = Path.join(this.backupDirPath, this.filename)

    this.serverVersion = version

    this.createdAt = Date.now()
  }
}
module.exports = Backup---
